export const updateSpaceInternalBodyStatusesBacklogNameMax = 24;

export const updateSpaceInternalBodyStatusesTodoNameMax = 24;

export const updateSpaceInternalBodyStatusesProgressNameMax = 24;

export const updateSpaceInternalBodyStatusesReviewNameMax = 24;

